// Auto-discovered registration for ui=4 screens and galleries.
// RULE (parallel packages): do NOT edit this file. Create a file named `register.ts`, `<name>-register.ts` or
// `<name>Register.ts` inside your own folder under ui/; it calls registerScreen(id, Component) and/or
// registerGallery(id, loader) from '<rel>/mount'. Every match is loaded in isolation: a broken package logs an
// error and cannot take down the other routes (found when one package's bad import blocked all `?ui=4` routes).
const loaders = import.meta.glob(['../**/register.ts', '../**/*-register.ts', '../**/*Register.ts']);

export const registered: Promise<void> = Promise.allSettled(
  Object.entries(loaders).map(async ([path, load]) => {
    try {
      await load();
    } catch (e) {
      console.error('[ui4] registration failed:', path, e);
    }
  }),
).then(() => undefined);
